    private static Map<String, EventInfo> buildEvents() {
        Map<String, EventInfo> map = new LinkedHashMap<>();
        map.put("o11y.telemetry.configured", new EventInfo("o11y.telemetry.configured", List.of(), List.of("o11y.config")));
        map.put("o11y.request.summary", new EventInfo("o11y.request.summary", List.of("http.request.method", "http.response.status_code", "o11y.outcome", "o11y.duration"), List.of()));
        map.put("o11y.telemetry.dropped", new EventInfo("o11y.telemetry.dropped", List.of("o11y.signal", "error.type"), List.of()));
        map.put("o11y.rum.error", new EventInfo("o11y.rum.error", List.of("o11y.rum.error.source", "exception.type", "session.id", "o11y.rum.view.id"), List.of()));
        map.put("o11y.rum.frustration", new EventInfo("o11y.rum.frustration", List.of("o11y.rum.frustration.type", "session.id", "o11y.rum.view.id"), List.of()));
        map.put("o11y.rum.session.start", new EventInfo("o11y.rum.session.start", List.of("session.id", "o11y.rum.platform"), List.of()));
        map.put("o11y.rum.session.end", new EventInfo("o11y.rum.session.end", List.of("session.id", "o11y.rum.session.retained"), List.of()));
        map.put("o11y.rum.view.summary", new EventInfo("o11y.rum.view.summary", List.of("o11y.rum.platform", "o11y.rum.view.id", "o11y.rum.view.name", "o11y.rum.view.kind", "session.id", "o11y.rum.summary.seq", "o11y.rum.summary.time_on_view"), List.of()));
        return Collections.unmodifiableMap(map);
    }

    private static Map<String, MetricInfo> buildMetrics() {
        Map<String, MetricInfo> map = new LinkedHashMap<>();
        map.put("o11y.schema.violations", new MetricInfo("o11y.schema.violations", InstrumentKind.COUNTER, "{violation}"));
        map.put("o11y.rum.vital.lcp", new MetricInfo("o11y.rum.vital.lcp", InstrumentKind.HISTOGRAM, "s"));
        map.put("o11y.rum.vital.inp", new MetricInfo("o11y.rum.vital.inp", InstrumentKind.HISTOGRAM, "s"));
        map.put("o11y.rum.vital.cls", new MetricInfo("o11y.rum.vital.cls", InstrumentKind.HISTOGRAM, "1"));
        map.put("o11y.rum.vital.fcp", new MetricInfo("o11y.rum.vital.fcp", InstrumentKind.HISTOGRAM, "s"));
        map.put("o11y.rum.vital.ttfb", new MetricInfo("o11y.rum.vital.ttfb", InstrumentKind.HISTOGRAM, "s"));
        map.put("o11y.rum.browser.long_animation_frames", new MetricInfo("o11y.rum.browser.long_animation_frames", InstrumentKind.COUNTER, "{frame}"));
        map.put("o11y.rum.views", new MetricInfo("o11y.rum.views", InstrumentKind.COUNTER, "{view}"));
        map.put("o11y.rum.errors", new MetricInfo("o11y.rum.errors", InstrumentKind.COUNTER, "{error}"));
        map.put("o11y.rum.frustrations", new MetricInfo("o11y.rum.frustrations", InstrumentKind.COUNTER, "{signal}"));
        return Collections.unmodifiableMap(map);
    }

    private static Map<String, List<String>> buildSpanRequired() {
        Map<String, List<String>> map = new LinkedHashMap<>();
        map.put("server", List.of("http.request.method", "url.path", "url.scheme"));
        map.put("client", List.of("http.request.method", "server.address", "server.port", "url.full"));
        return Collections.unmodifiableMap(map);
    }

    private static Map<String, List<String>> buildRumSpanRequired() {
        Map<String, List<String>> map = new LinkedHashMap<>();
        map.put("view", List.of("o11y.rum.span.shape", "o11y.rum.platform", "o11y.rum.view.name", "o11y.rum.view.id", "o11y.rum.view.kind", "session.id"));
        map.put("action", List.of("o11y.rum.span.shape", "o11y.rum.action.type", "o11y.rum.view.id", "session.id"));
        map.put("app_load", List.of("o11y.rum.span.shape", "o11y.rum.platform", "o11y.rum.view.id", "session.id"));
        return Collections.unmodifiableMap(map);
    }

